WITH fixture(id, first_name) AS (VALUES ('a', NULL::text), ('b', NULL::text), ('c', 'A'), ('d', 'A'), ('e', 'B'), ('f', 'C')), actual AS (SELECT t0."id"::text AS key0 FROM fixture t0 WHERE TRUE AND ((t0."first_name" > 'A') OR (t0."first_name" IS NOT DISTINCT FROM 'A' AND t0."id" > 'c')) ORDER BY t0."first_name" asc NULLS FIRST, t0."id" asc NULLS FIRST) SELECT 'asc-value' AS scenario, array_agg(key0) = ARRAY['d', 'e', 'f'] AS passed FROM actual;
WITH fixture(id, first_name) AS (VALUES ('a', NULL::text), ('b', NULL::text), ('c', 'A'), ('d', 'A'), ('e', 'B'), ('f', 'C')), actual AS (SELECT t0."id"::text AS key0 FROM fixture t0 WHERE TRUE AND ((t0."first_name" IS NOT NULL) OR (t0."first_name" IS NOT DISTINCT FROM NULL AND t0."id" > 'a')) ORDER BY t0."first_name" asc NULLS FIRST, t0."id" asc NULLS FIRST) SELECT 'asc-null' AS scenario, array_agg(key0) = ARRAY['b', 'c', 'd', 'e', 'f'] AS passed FROM actual;
WITH fixture(id, first_name) AS (VALUES ('a', NULL::text), ('b', NULL::text), ('c', 'A'), ('d', 'A'), ('e', 'B'), ('f', 'C')), actual AS (SELECT t0."id"::text AS key0 FROM fixture t0 WHERE TRUE AND (((t0."first_name" < 'A' OR t0."first_name" IS NULL)) OR (t0."first_name" IS NOT DISTINCT FROM 'A' AND t0."id" > 'c')) ORDER BY t0."first_name" desc NULLS LAST, t0."id" asc NULLS FIRST) SELECT 'desc-value' AS scenario, array_agg(key0) = ARRAY['d', 'a', 'b'] AS passed FROM actual;
WITH fixture(id, first_name) AS (VALUES ('a', NULL::text), ('b', NULL::text), ('c', 'A'), ('d', 'A'), ('e', 'B'), ('f', 'C')), actual AS (SELECT t0."id"::text AS key0 FROM fixture t0 WHERE TRUE AND ((FALSE) OR (t0."first_name" IS NOT DISTINCT FROM NULL AND t0."id" > 'a')) ORDER BY t0."first_name" desc NULLS LAST, t0."id" asc NULLS FIRST) SELECT 'desc-null' AS scenario, array_agg(key0) = ARRAY['b'] AS passed FROM actual;
WITH fixture(id, first_name) AS (VALUES ('a', NULL::text), ('b', NULL::text), ('c', 'A'), ('d', 'A'), ('e', 'B'), ('f', 'C')), actual AS (SELECT t0."id"::text AS key0 FROM fixture t0 WHERE TRUE AND ((FALSE) OR (t0."first_name" IS NOT DISTINCT FROM NULL AND t0."id" > 'a') OR (t0."first_name" IS NOT DISTINCT FROM NULL AND t0."id" IS NOT DISTINCT FROM 'a')) ORDER BY t0."first_name" desc NULLS LAST, t0."id" asc NULLS FIRST) SELECT 'desc-null-inclusive' AS scenario, array_agg(key0) = ARRAY['a', 'b'] AS passed FROM actual;